import 'package:flutter/material.dart'  import 'package:flutter_riverpod/flutter_riverpod.dart'  import 'package:go_router/go_router.dart'  import '../api/api_client.dart'  import '../providers/auth_provider.dart'  import '../widgets/loading_widget.dart'    class ProfileScreen extends ConsumerStatefulWidget {    const ProfileScreen({super.key})      @override    ConsumerState<ProfileScreen> createState() => _ProfileScreenState()  }    class _ProfileScreenState extends ConsumerState<ProfileScreen> {    Map<String, dynamic>? _profile    bool _isLoading = true    bool _isEditing = false      final _nameController = TextEditingController()    final _phoneController = TextEditingController()    final _companyController = TextEditingController()      @override    void initState() {      super.initState()      _loadProfile()    }      Future<void> _loadProfile() async {      try {        final profile = await ApiClient().getProfile()        if (mounted) {          setState(() {            _profile = profile            _isLoading = false          })          _nameController.text = profile['full_name'] ?? ''          _phoneController.text = profile['phone'] ?? ''          _companyController.text = profile['company'] ?? ''        }      } catch (e) {        if (mounted) setState(() => _isLoading = false)      }    }      Future<void> _saveProfile() async {      try {        await ApiClient().updateProfile({          'full_name': _nameController.text,          'phone': _phoneController.text,          'company': _companyController.text,        })        if (mounted) {          setState(() => _isEditing = false)          _loadProfile()          ScaffoldMessenger.of(context).showSnackBar(            const SnackBar(content: Text('Профиль обновлен')),          )        }      } catch (e) {        if (mounted) {          ScaffoldMessenger.of(context).showSnackBar(            SnackBar(content: Text('Ошибка: $e')),          )        }      }    }      Future<void> _logout() async {      await ApiClient().logout()      ref.read(authProvider.notifier).state = false      ref.read(userProvider.notifier).state = null      if (mounted) context.go('/login')    }      @override    Widget build(BuildContext context) {      return Scaffold(        appBar: AppBar(          title: const Text('Профиль'),          actions: [            if (!_isEditing)              IconButton(                icon: const Icon(Icons.edit),                onPressed: () => setState(() => _isEditing = true),              )            else              IconButton(                icon: const Icon(Icons.check),                onPressed: _saveProfile,              ),          ],        ),        body: _isLoading            ? const LoadingWidget()            : SingleChildScrollView(                padding: const EdgeInsets.all(16),                child: Column(                  children: [                    // Avatar                    CircleAvatar(                      radius: 50,                      backgroundColor: Theme.of(context).colorScheme.primary,                      child: Text(                        (_profile?['full_name'] ?? _profile?['email'] ?? 'U')[0].toUpperCase(),                        style: const TextStyle(fontSize: 36, color: Colors.white, fontWeight: FontWeight.bold),                      ),                    ),                    const SizedBox(height: 16),                    Text(                      _profile?['full_name'] ?? 'Пользователь',                      style: const TextStyle(fontSize: 22, fontWeight: FontWeight.bold),                    ),                    const SizedBox(height: 4),                    Text(                      _profile?['email'] ?? '',                      style: TextStyle(fontSize: 14, color: Colors.grey[600]),                    ),                    const SizedBox(height: 4),                    Container(                      padding: const EdgeInsets.symmetric(horizontal: 12, vertical: 4),                      decoration: BoxDecoration(                        color: Theme.of(context).colorScheme.primary.withOpacity(0.1),                        borderRadius: BorderRadius.circular(20),                      ),                      child: Text(                        (_profile?['tier'] ?? 'free').toString().toUpperCase(),                        style: TextStyle(                          fontSize: 12,                          color: Theme.of(context).colorScheme.primary,                          fontWeight: FontWeight.w600,                        ),                      ),                    ),                    const SizedBox(height: 32),                      // Info cards                    _InfoCard(                      icon: Icons.person_outline,                      title: 'Полное имя',                      value: _profile?['full_name'] ?? 'Не указано',                      isEditing: _isEditing,                      controller: _nameController,                    ),                    const SizedBox(height: 12),                    _InfoCard(                      icon: Icons.phone_outlined,                      title: 'Телефон',                      value: _profile?['phone'] ?? 'Не указан',                      isEditing: _isEditing,                      controller: _phoneController,                    ),                    const SizedBox(height: 12),                    _InfoCard(                      icon: Icons.business_outlined,                      title: 'Компания',                      value: _profile?['company'] ?? 'Не указана',                      isEditing: _isEditing,                      controller: _companyController,                    ),                    const SizedBox(height: 12),                    _InfoCard(                      icon: Icons.badge_outlined,                      title: 'ИНН',                      value: _profile?['inn'] ?? 'Не указан',                      isEditing: false,                    ),                    const SizedBox(height: 12),                    _InfoCard(                      icon: Icons.calendar_today_outlined,                      title: 'Дата регистрации',                      value: _profile?['created_at'] != null                          ? '${DateTime.parse(_profile!['created_at']).day.toString().padLeft(2, '0')}.${DateTime.parse(_profile!['created_at']).month.toString().padLeft(2, '0')}.${DateTime.parse(_profile!['created_at']).year}'                          : '—',                      isEditing: false,                    ),                    const SizedBox(height: 32),                      // Settings                    const Text('Настройки', style: TextStyle(fontSize: 18, fontWeight: FontWeight.bold)),                    const SizedBox(height: 12),                    _SettingsTile(                      icon: Icons.notifications_outlined,                      title: 'Уведомления',                      subtitle: 'Настройка push и email',                      onTap: () {},                    ),                    _SettingsTile(                      icon: Icons.security_outlined,                      title: 'Безопасность',                      subtitle: 'Смена пароля, 2FA',                      onTap: () {},                    ),                    _SettingsTile(                      icon: Icons.credit_card_outlined,                      title: 'Подписка',                      subtitle: 'Тариф и оплата',                      onTap: () {},                    ),                    const SizedBox(height: 32),                      // Logout                    SizedBox(                      width: double.infinity,                      child: ElevatedButton.icon(                        onPressed: _logout,                        icon: const Icon(Icons.logout),                        label: const Text('Выйти'),                        style: ElevatedButton.styleFrom(                          backgroundColor: Colors.red[50],                          foregroundColor: Colors.red,                          padding: const EdgeInsets.symmetric(vertical: 16),                          shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(12)),                        ),                      ),                    ),                    const SizedBox(height: 16),                    Text(                      'Мир Самозанятых v8.5.0',                      style: TextStyle(fontSize: 12, color: Colors.grey[400]),                      textAlign: TextAlign.center,                    ),                  ],                ),              ),      )    }  }    class _InfoCard extends StatelessWidget {    final IconData icon    final String title    final String value    final bool isEditing    final TextEditingController? controller      const _InfoCard({      required this.icon,      required this.title,      required this.value,      this.isEditing = false,      this.controller,    })      @override    Widget build(BuildContext context) {      return Card(        child: Padding(          padding: const EdgeInsets.all(16),          child: Row(            children: [              Icon(icon, color: Colors.grey[400]),              const SizedBox(width: 16),              Expanded(                child: Column(                  crossAxisAlignment: CrossAxisAlignment.start,                  children: [                    Text(title, style: TextStyle(fontSize: 12, color: Colors.grey[600])),                    const SizedBox(height: 4),                    if (isEditing && controller != null)                      TextField(                        controller: controller,                        decoration: const InputDecoration(                          isDense: true,                          contentPadding: EdgeInsets.zero,                          border: InputBorder.none,                        ),                        style: const TextStyle(fontSize: 16, fontWeight: FontWeight.w600),                      )                    else                      Text(value, style: const TextStyle(fontSize: 16, fontWeight: FontWeight.w600)),                  ],                ),              ),            ],          ),        ),      )    }  }    class _SettingsTile extends StatelessWidget {    final IconData icon    final String title    final String subtitle    final VoidCallback onTap      const _SettingsTile({      required this.icon,      required this.title,      required this.subtitle,      required this.onTap,    })      @override    Widget build(BuildContext context) {      return Card(        margin: const EdgeInsets.only(bottom: 8),        child: ListTile(          leading: Icon(icon, color: Theme.of(context).colorScheme.primary),          title: Text(title, style: const TextStyle(fontWeight: FontWeight.w600)),          subtitle: Text(subtitle, style: TextStyle(fontSize: 12, color: Colors.grey[600])),          trailing: const Icon(Icons.chevron_right, color: Colors.grey),          onTap: onTap,        ),      )    }  }